":[{"id":"q1","text":{"en":"A caller says your bank account will close unless you tell them the OTP.","hi":"एक व्यक्ति कहता है कि OTP न बताने पर बैंक खाता बंद हो जाएगा।","mr":"एक व्यक्ती म्हणते की OTP न सांगितल्यास बँक खाते बंद होईल."},"safe":false},{"id":"q2","text":{"en":"You call the phone number printed on the back of your bank card.","hi":"आप बैंक कार्ड के पीछे दिया नंबर मिलाते हैं।","mr":"तुम्ही बँक कार्डच्या मागे दिलेल्या नंबरवर फोन करता."},"safe":true},{"id":"q3","text":{"en":"A stranger sends a link and asks you to claim a surprise prize.","hi":"कोई अनजान व्यक्ति लिंक भेजकर इनाम लेने को कहता है।","mr":"अनोळखी व्यक्ती लिंक पाठवून बक्षीस घेण्यास सांगते."},"safe":false},{"id":"q4","text":{"en":"You use a long password that is different from your other passwords.","hi":"आप लंबा पासवर्ड रखते हैं जो दूसरे पासवर्ड से अलग है।","mr":"तुम्ही इतर पासवर्डपेक्षा वेगळा आणि मोठा पासवर्ड वापरता."},"safe":true},{"id":"q5","text":{"en":"A caller asks you to install an app so they can fix your bank account.","hi":"एक व्यक्ति बैंक खाता ठीक करने के लिए ऐप इंस्टॉल करने को कहता है।","mr":"बँक खाते दुरुस्त करण्यासाठी एक व्यक्ती अॅप बसवायला सांगते."},"safe":false},{"id":"q6","text":{"en":"A family member calls from their usual number to check on you.","hi":"परिवार का सदस्य अपने जाने-पहचाने नंबर से हाल पूछता है।","mr":"कुटुंबातील व्यक्ती नेहमीच्या नंबरवरून तुमची विचारपूस करते."},"safe":true},{"id":"q7","text":{"en":"A message says to share your UPI PIN to receive a refund.","hi":"संदेश में पैसे वापस पाने के लिए UPI PIN माँगा गया है।","mr":"परतावा मिळवण्यासाठी मेसेजमध्ये UPI PIN मागितला आहे."},"safe":false},{"id":"q8","text":{"en":"You check with a known family member before opening an unexpected link.","hi":"अनजान लिंक खोलने से पहले आप परिवार के सदस्य से पूछते हैं।","mr":"अनोळखी लिंक उघडण्यापूर्वी तुम्ही कुटुंबातील व्यक्तीला विचारता."},"safe":true},{"id":"q9","text":{"en":"A caller says they are customer care and asks to see your screen.","hi":"एक व्यक्ति ग्राहक सेवा बताकर आपकी स्क्रीन देखने को कहता है।","mr":"ग्राहक सेवा असल्याचे सांगून एक व्यक्ती तुमची स्क्रीन पाहण्यास सांगते."},"safe":false},{"id":"q10","text":{"en":"You keep your phone lock code private, even from someone who calls unexpectedly.","hi":"अचानक फोन करने वाले व्यक्ति से भी आप फ़ोन का लॉक कोड गुप्त रखते हैं।","mr":"अचानक फोन करणाऱ्या व्यक्तीपासूनही तुम्ही फोनचा लॉक कोड गुप्त ठेवता."},"safe":true}],"suggestions":[{"en":"How do I send a voice message?","hi":"आवाज़ वाला संदेश कैसे भेजें?","mr":"व्हॉइस मेसेज कसा पाठवायचा?"},{"en":"How do I make a video call?","hi":"वीडियो कॉल कैसे करें?","mr":"व्हिडिओ कॉल कसा करायचा?"},{"en":"What is an OTP?","hi":"OTP क्या है?","mr":"OTP म्हणजे काय?"},{"en":"How do I increase brightness?","hi":"स्क्रीन की रोशनी कैसे बढ़ाएँ?","mr":"स्क्रीनचा उजेड कसा वाढवायचा?"}],"assistant":{"lessonSteps":{"wa-voice":{"en":["Open WhatsApp and choose the person you want to talk to.","Press and hold the microphone. Speak while holding it.","Let go to send. Slide left before letting go if you want to cancel."],"hi":["व्हाट्सऐप खोलें और उस व्यक्ति की बातचीत चुनें।","माइक्रोफ़ोन दबाकर रखें और बोलें।","भेजने के लिए छोड़ें। रद्द करने के लिए छोड़ने से पहले बाईं ओर खिसकाएँ।"],"mr":["व्हॉट्सअॅप उघडा आणि ज्या व्यक्तीशी बोलायचे आहे ती चॅट निवडा.","मायक्रोफोन दाबून ठेवा आणि बोला.","पाठवण्यासाठी बोट सोडा. रद्द करण्यासाठी सोडण्याआधी डावीकडे सरकवा."]},"wa-video":{"en":["Open the person’s chat in WhatsApp.","Tap the small video camera near their name.","Wait for them to answer. Tap the red button to end the call."],"hi":["व्हाट्सऐप में उस व्यक्ति की बातचीत खोलें।","नाम के पास वीडियो कैमरा दबाएँ।","उनके जवाब का इंतज़ार करें। कॉल बंद करने के लिए लाल बटन दबाएँ।"],"mr":["व्हॉट्सअॅपमध्ये त्या व्यक्तीची चॅट उघडा.","नावाजवळील व्हिडिओ कॅमेरा दाबा.","त्यांनी उत्तर देण्याची वाट पाहा. कॉल बंद करण्यासाठी लाल बटण दाबा."]},"brightness":{"en":["Swipe down from the very top of the screen.","Find the sun symbol and its brightness bar.","Move the bar right for a brighter screen, or left for a dimmer one."],"hi":["स्क्रीन के सबसे ऊपर से नीचे की ओर खींचें।","सूरज के निशान और रोशनी वाली पट्टी को ढूँढ़ें।","रोशनी बढ़ाने के लिए पट्टी दाईं ओर और कम करने के लिए बाईं ओर खिसकाएँ।"],"mr":["स्क्रीनच्या अगदी वरून खाली सरकवा.","सूर्याचे चिन्ह आणि उजेडाची पट्टी शोधा.","उजेड वाढवण्यासाठी पट्टी उजवीकडे आणि कमी करण्यासाठी डावीकडे सरकवा."]},"wifi":{"en":["Open Settings, then tap Wi-Fi or Network.","Switch Wi-Fi on and choose a network you know.","Enter its password only if you trust the network owner."],"hi":["सेटिंग खोलें और वाई-फ़ाई या नेटवर्क दबाएँ।","वाई-फ़ाई चालू करें और जाना-पहचाना नेटवर्क चुनें।","पासवर्ड तभी डालें जब नेटवर्क पर भरोसा हो।"],"mr":["सेटिंग उघडा आणि वाय-फाय किंवा नेटवर्क दाबा.","वाय-फाय सुरू करा आणि ओळखीचे नेटवर्क निवडा.","नेटवर्कवर विश्वास असेल तरच पासवर्ड टाका."]},"make-call":{"en":["Open the Phone app and tap Contacts.","Choose someone you know, such as Asha.","Tap the phone symbol. This practice screen will not call anyone."],"hi":["फ़ोन ऐप खोलें और संपर्क दबाएँ।","किसी जाने-पहचाने व्यक्ति को चुनें, जैसे आशा।","फ़ोन के निशान पर दबाएँ। यह अभ्यास किसी को कॉल नहीं करेगा।"],"mr":["फोन अॅप उघडा आणि संपर्क दाबा.","आशासारख्या ओळखीच्या व्यक्तीचे नाव निवडा.","फोनच्या चिन्हावर दाबा. या सरावातून कोणालाही कॉल जाणार नाही."]},"video-call":{"en":["Open a trusted person’s chat or contact.","Tap the video camera symbol to begin.","When you are done, tap the red end-call button. This is only a simulation."],"hi":["किसी भरोसेमंद व्यक्ति की बातचीत या संपर्क खोलें।","शुरू करने के लिए वीडियो कैमरा दबाएँ।","बात पूरी होने पर लाल कॉल-बंद बटन दबाएँ। यह सिर्फ़ अभ्यास है।"],"mr":["विश्वासू व्यक्तीची चॅट किंवा संपर्क उघडा.","सुरू करण्यासाठी व्हिडिओ कॅमेरा दाबा.","बोलून झाल्यावर लाल कॉल बंद बटण दाबा. हा फक्त सराव आहे."]},"otp":{"en":["An OTP is a one-time code sent to your phone to check it is really you.","Use the code only in the app or website you opened yourself.","Never tell the code to a caller or send it in a message."],"hi":["OTP एक बार का कोड है जो यह जाँचता है कि फ़ोन आपका है।","कोड सिर्फ़ उसी ऐप या वेबसाइट में डालें जिसे आपने खुद खोला हो।","किसी को फ़ोन पर या संदेश में यह कोड न बताएँ।"],"mr":["OTP हा तुमची खात्री करण्यासाठी फोनवर येणारा एकदाच वापरायचा कोड आहे.","तुम्ही स्वतः उघडलेल्या अॅप किंवा वेबसाइटवरच तो टाका.","फोनवर किंवा मेसेजमध्ये हा कोड कोणालाही सांगू नका."]},"upi-pin":{"en":["A UPI PIN is a private number used to approve a payment.","You may need it when you send money, not when you receive money.","Never share it with anyone. This app will never ask you for it."],"hi":["UPI PIN भुगतान की मंज़ूरी के लिए इस्तेमाल होने वाला गुप्त नंबर है।","पैसे भेजते समय इसकी ज़रूरत पड़ सकती है, पाने के लिए नहीं।","इसे किसी को न बताएँ। यह ऐप आपसे PIN नहीं माँगेगा।"],"mr":["UPI PIN हा पेमेंट मंजूर करण्यासाठी वापरला जाणारा गुप्त क्रमांक आहे.","पैसे पाठवताना तो लागू शकतो; पैसे मिळवताना नाही.","तो कोणालाही सांगू नका. हे अॅप PIN विचारणार नाही."]},"passwords":{"en":["Choose a long password that is hard for others to guess.","Do not use the same password everywhere.","Do not share it in a call, message or on this practice app."],"hi":["लंबा पासवर्ड चुनें जिसका अंदाज़ा लगाना मुश्किल हो।","हर जगह एक ही पासवर्ड न रखें।","इसे कॉल, संदेश या इस अभ्यास ऐप में न बताएँ।"],"mr":["इतरांना ओळखता येणार नाही असा मोठा पासवर्ड निवडा.","सगळीकडे एकच पासवर्ड वापरू नका.","तो कॉल, मेसेज किंवा या सराव अॅपमध्ये सांगू नका."]}},"lessonTips":{"unlock":{"en":"Press the side power button to wake the screen. Swipe up, then use your own screen lock.","hi":"स्क्रीन जगाने के लिए किनारे का पावर बटन दबाएँ। ऊपर खींचें और अपना स्क्रीन लॉक खोलें।","mr":"स्क्रीन सुरू करण्यासाठी बाजूचे पॉवर बटण दाबा. वर सरकवा आणि तुमचा स्क्रीन लॉक उघडा."},"volume":{"en":"Press the side volume buttons. The top button makes sound louder; the lower button makes it softer.","hi":"किनारे के आवाज़ वाले बटन दबाएँ। ऊपर वाला आवाज़ बढ़ाता है और नीचे वाला कम करता है।","mr":"बाजूची आवाजेची बटणे दाबा. वरचे बटण आवाज वाढवते आणि खालचे कमी करते."},"mobile-data":{"en":"Open Settings, choose Network or SIM, then switch Mobile data on. It may use your phone plan.","hi":"सेटिंग में नेटवर्क या SIM चुनें और मोबाइल डेटा चालू करें। इसमें आपके फ़ोन प्लान का डेटा लगेगा।","mr":"सेटिंगमध्ये नेटवर्क किंवा SIM निवडा आणि मोबाइल डेटा सुरू करा. यासाठी तुमच्या फोन प्लॅनचा डेटा वापरला जाऊ शकतो."},"open-apps":{"en":"Find the app picture on your Home screen and tap it once to open.","hi":"होम स्क्रीन पर ऐप का चित्र ढूँढ़ें और खोलने के लिए एक बार दबाएँ।","mr":"होम स्क्रीनवर अॅपचे चित्र शोधा आणि उघडण्यासाठी एकदा दाबा."},"close-apps":{"en":"Swipe up from the bottom and pause to see open apps. Swipe an app up to close it.","hi":"नीचे से ऊपर खींचकर रुकें और खुले ऐप देखें। ऐप बंद करने के लिए उसे ऊपर खिसकाएँ।","mr":"खालून वर सरकवून थांबा आणि उघडी अॅप्स पाहा. अॅप बंद करण्यासाठी वर सरकवा."},"contacts":{"en":"Open Contacts. Tap a name to see the saved phone number and other details.","hi":"संपर्क खोलें। सहेजा नंबर और जानकारी देखने के लिए नाम दबाएँ।","mr":"संपर्क उघडा. जतन केलेला फोन नंबर आणि माहिती पाहण्यासाठी नाव दाबा."},"camera":{"en":"Open Camera. Point the phone at what you want to photograph, then tap the large round button.","hi":"कैमरा खोलें। फ़ोन को उस चीज़ की ओर रखें जिसकी तस्वीर लेनी है, फिर बड़ा गोल बटन दबाएँ।","mr":"कॅमेरा उघडा. ज्याचा फोटो घ्यायचा आहे त्याकडे फोन धरा आणि मोठे गोल बटण दाबा."},"screenshot":{"en":"On most phones, press the power and volume-down buttons together for a moment.","hi":"अधिकतर फ़ोन में पावर और आवाज़ कम करने वाले बटन एक साथ थोड़ी देर दबाएँ।","mr":"बहुतेक फोनमध्ये पॉवर आणि आवाज कमी करण्याचे बटण एकत्र थोडा वेळ दाबा."},"language-settings":{"en":"In Settings, look for System or General management, then Languages. Choose a language you know.","hi":"सेटिंग में सिस्टम या सामान्य प्रबंधन, फिर भाषा चुनें। अपनी जानी भाषा चुनें।","mr":"सेटिंगमध्ये सिस्टम किंवा सामान्य व्यवस्थापन, नंतर भाषा निवडा. तुम्हाला येणारी भाषा निवडा."},"settings-basics":{"en":"The gear picture opens Settings. Choose one item at a time and go back if something looks unfamiliar.","hi":"गियर का चित्र सेटिंग खोलता है। एक बार में एक चीज़ चुनें। अनजान लगे तो वापस जाएँ।","mr":"गियरचे चित्र सेटिंग उघडते. एका वेळी एकच गोष्ट निवडा. अनोळखी वाटल्यास मागे जा."},"wa-open":{"en":"Find the green WhatsApp picture on your Home screen and tap it once.","hi":"होम स्क्रीन पर हरे व्हाट्सऐप चित्र को ढूँढ़ें और एक बार दबाएँ।","mr":"होम स्क्रीनवर हिरवे व्हॉट्सअॅप चित्र शोधा आणि एकदा दाबा."},"wa-chat":{"en":"On the Chats screen, tap the name of the person you want to talk with.","hi":"चैट स्क्रीन पर उस व्यक्ति का नाम दबाएँ जिससे बात करनी है।","mr":"चॅट स्क्रीनवर ज्या व्यक्तीशी बोलायचे आहे तिचे नाव दाबा."},"wa-text":{"en":"Tap the message box, type a short message, then tap the send arrow.","hi":"संदेश लिखने की जगह दबाएँ, छोटा संदेश लिखें और भेजने का तीर दबाएँ।","mr":"मेसेज लिहायची जागा दाबा, छोटा मेसेज लिहा आणि पाठवण्याचे बाण दाबा."},"wa-photo":{"en":"In a chat, tap the attachment or camera picture. Choose a photo and check it before sending.","hi":"बातचीत में अटैचमेंट या कैमरा चित्र दबाएँ। तस्वीर चुनें और भेजने से पहले देख लें।","mr":"चॅटमध्ये जोडणीचे किंवा कॅमेऱ्याचे चित्र दाबा. फोटो निवडा आणि पाठवण्याआधी तपासा."},"wa-save":{"en":"Open Contacts on your phone, tap Add, enter a name and number, then save.","hi":"फ़ोन के संपर्क खोलें, जोड़ें दबाएँ, नाम और नंबर लिखें और सहेजें।","mr":"फोनमधील संपर्क उघडा, जोडा दाबा, नाव आणि नंबर लिहा आणि जतन करा."},"wa-block":{"en":"Open the unknown person’s chat, tap their name, then choose Block or Report. Do not reply first.","hi":"अनजान व्यक्ति की बातचीत खोलें, नाम दबाएँ और ब्लॉक या शिकायत चुनें। पहले जवाब न दें।","mr":"अनोळखी व्यक्तीची चॅट उघडा, नाव दाबा आणि ब्लॉक किंवा तक्रार निवडा. आधी उत्तर देऊ नका."},"wa-privacy":{"en":"Open Settings, choose Privacy, and decide who can see your photo and last-seen time.","hi":"सेटिंग में निजता चुनें और तय करें कि आपकी तस्वीर और पिछली बार का समय कौन देखे।","mr":"सेटिंगमध्ये गोपनीयता निवडा आणि तुमचा फोटो व शेवटची वेळ कोण पाहू शकते ते ठरवा."},"answer-call":{"en":"When the phone rings, swipe or tap the green answer button. You can let an unknown call ring out.","hi":"फ़ोन बजने पर हरा जवाब बटन दबाएँ या खिसकाएँ। अनजान कॉल को बजने दें।","mr":"फोन वाजल्यावर हिरवे उत्तर बटण दाबा किंवा सरकवा. अनोळखी कॉल उचलणे आवश्यक नाही."},"end-call":{"en":"Tap the red phone button on the screen to end the call.","hi":"कॉल बंद करने के लिए स्क्रीन पर लाल फ़ोन बटन दबाएँ।","mr":"कॉल बंद करण्यासाठी स्क्रीनवरील लाल फोन बटण दाबा."},"speaker":{"en":"During a call, tap Speaker to hear the other person without holding the phone to your ear.","hi":"कॉल के दौरान स्पीकर दबाएँ ताकि फ़ोन कान से लगाए बिना सुन सकें।","mr":"कॉलदरम्यान स्पीकर दाबा, म्हणजे फोन कानाला न लावता ऐकू येईल."},"call-history":{"en":"Open the Phone app and tap Recent or Call history to see calls you made and received.","hi":"फ़ोन ऐप में हाल के कॉल या कॉल सूची दबाकर किए और आए कॉल देखें।","mr":"फोन अॅपमध्ये अलीकडील किंवा कॉल यादी दाबून केलेले आणि आलेले कॉल पाहा."},"save-contact":{"en":"Open Contacts, tap Add, enter the person’s name and number, then tap Save.","hi":"संपर्क खोलें, जोड़ें दबाएँ, नाम और नंबर लिखकर सहेजें।","mr":"संपर्क उघडा, जोडा दाबा, नाव आणि नंबर लिहून जतन करा."},"voice-typing":{"en":"Tap a text box, tap the small microphone on the keyboard, speak clearly, then check the words.","hi":"लिखने की जगह दबाएँ, कीबोर्ड का छोटा माइक्रोफ़ोन दबाएँ, साफ़ बोलें और लिखे शब्द जाँचें।","mr":"लिहायची जागा दाबा, कीबोर्डवरील छोटा मायक्रोफोन दाबा, स्पष्ट बोला आणि शब्द तपासा."},"microphone":{"en":"When an app asks to use the microphone, allow it only if you started a voice feature you trust.","hi":"ऐप माइक्रोफ़ोन की अनुमति माँगे तो तभी दें जब आपने भरोसेमंद आवाज़ वाला काम शुरू किया हो।","mr":"अॅपने मायक्रोफोनची परवानगी मागितल्यास, विश्वासू आवाजाचे फीचर तुम्ही सुरू केले असेल तरच द्या."},"voice-search":{"en":"Tap the microphone beside Search, say what you are looking for, then check the results.","hi":"खोज के पास माइक्रोफ़ोन दबाएँ, जो ढूँढ़ना है बोलें और नतीजे जाँचें।","mr":"शोधाजवळचा मायक्रोफोन दाबा, काय शोधायचे ते बोला आणि निकाल तपासा."},"assistant":{"en":"Say a short question, such as “What is the weather?” Do not ask it to share passwords or bank details.","hi":"छोटा सवाल बोलें, जैसे “मौसम कैसा है?” पासवर्ड या बैंक जानकारी न माँगें।","mr":"“आजचे हवामान कसे आहे?” असा छोटा प्रश्न विचारा. पासवर्ड किंवा बँक माहिती विचारू नका."},"upi":{"en":"UPI is a way to send money between bank accounts using a payment app. Never share your UPI PIN.","hi":"UPI भुगतान ऐप से बैंक खातों में पैसे भेजने का तरीका है। अपना UPI PIN कभी न बताएँ।","mr":"UPI हा पेमेंट अॅपने बँक खात्यांमध्ये पैसे पाठवण्याचा मार्ग आहे. UPI PIN कधीही सांगू नका."},"qr":{"en":"A QR code is a square pattern a phone camera can read. Check the name and amount before paying.","hi":"QR कोड चौकोर निशान है जिसे फ़ोन कैमरा पढ़ सकता है। भुगतान से पहले नाम और रकम जाँचें।","mr":"QR कोड हा फोनचा कॅमेरा वाचू शकणारा चौकोनी नमुना आहे. पैसे देण्याआधी नाव आणि रक्कम तपासा."},"payment-safety":{"en":"Check who will receive the money and the amount. A PIN approves sending money; never share it to receive money.","hi":"पैसा किसे और कितना जाएगा, जाँचें। PIN पैसे भेजने की मंज़ूरी है; पाने के लिए न बताएँ।","mr":"पैसे कोणाला आणि किती जाणार ते तपासा. PIN पैसे पाठवण्याची मंजुरी आहे; मिळवण्यासाठी तो सांगू नका."},"payment-scams":{"en":"Pause if someone rushes you, asks for a PIN or OTP, or offers a surprise refund. Call your bank using its official number.","hi":"कोई जल्दी करे, PIN या OTP माँगे या अचानक रिफंड कहे तो रुकें। बैंक के आधिकारिक नंबर पर खुद कॉल करें।","mr":"कोणी घाई करायला लावत असेल, PIN किंवा OTP मागत असेल किंवा परतावा देत असेल तर थांबा. बँकेच्या अधिकृत नंबरवर फोन करा."},"otp-safety":{"en":"An OTP belongs only to you. A bank, helper or caller should never ask you to read it out.","hi":"OTP सिर्फ़ आपका है। बैंक, मददगार या कॉल करने वाला आपसे इसे कभी नहीं पूछेगा।","mr":"OTP फक्त तुमच्यासाठी आहे. बँक, मदतनीस किंवा फोन करणारी व्यक्ती तो कधीही मागणार नाही."},"links":{"en":"Do not open an unexpected link. Check who sent it by contacting them another way first.","hi":"अचानक आई लिंक न खोलें। पहले किसी दूसरे तरीके से भेजने वाले की पुष्टि करें।","mr":"अचानक आलेली लिंक उघडू नका. आधी दुसऱ्या मार्गाने पाठवणाऱ्याची खात्री करा."},"fake-calls":{"en":"Do not trust the name shown on caller ID alone. Hang up and call the official number you already know.","hi":"सिर्फ़ स्क्रीन पर दिखे नाम पर भरोसा न करें। फ़ोन काटें और जाना-पहचाना आधिकारिक नंबर मिलाएँ।","mr":"स्क्रीनवर दिसणाऱ्या नावावरच विश्वास ठेवू नका. फोन ठेवा आणि ओळखीच्या अधिकृत नंबरवर फोन करा."},"fake-messages":{"en":"Be careful with urgent messages about prizes, blocked accounts or parcels. Check with the company directly.","hi":"इनाम, बंद खाते या पार्सल के जल्दबाज़ी वाले संदेश से सावधान रहें। कंपनी से खुद पूछें।","mr":"बक्षीस, बंद खाते किंवा पार्सलबद्दलच्या घाईच्या मेसेजपासून सावध राहा. कंपनीशी थेट संपर्क करा."},"fake-support":{"en":"Find customer-care numbers on the company’s official app or card. Never pay a stranger to unlock your account.","hi":"ग्राहक सेवा नंबर कंपनी के आधिकारिक ऐप या कार्ड पर देखें। खाता खोलने के लिए अनजान को पैसे न दें।","mr":"ग्राहक सेवा नंबर कंपनीच्या अधिकृत अॅप किंवा कार्डवर पाहा. खाते उघडण्यासाठी अनोळखी व्यक्तीला पैसे देऊ नका."},"screen-sharing":{"en":"Do not install a screen-sharing app for an unexpected caller. They could see private information on your phone.","hi":"अनजान कॉल करने वाले के कहने पर स्क्रीन दिखाने वाला ऐप न डालें। वह निजी जानकारी देख सकता है।","mr":"अनोळखी व्यक्तीच्या सांगण्यावरून स्क्रीन शेअरिंग अॅप बसवू नका. ती तुमची खाजगी माहिती पाहू शकते."},"privacy":{"en":"Share your photos and personal details only with people you know. Review who can see your profile.","hi":"तस्वीरें और निजी जानकारी सिर्फ़ जाने-पहचाने लोगों से साझा करें। अपनी प्रोफ़ाइल देखने वालों की जाँच करें।","mr":"फोटो आणि वैयक्तिक माहिती फक्त ओळखीच्या लोकांसोबत शेअर करा. तुमची माहिती कोण पाहू शकते ते तपासा."},"report-scams":{"en":"Stop replying, save the message, and tell someone you trust. Contact your bank using its official number if money is involved.","hi":"जवाब देना बंद करें, संदेश सहेजें और भरोसेमंद व्यक्ति को बताएँ। पैसे की बात हो तो बैंक के आधिकारिक नंबर पर संपर्क करें।","mr":"उत्तर देणे थांबवा, मेसेज जतन करा आणि विश्वासू व्यक्तीला सांगा. पैशांचा प्रश्न असल्यास बँकेच्या अधिकृत नंबरवर संपर्क करा."}},"faq":[{"terms":["voice message","voice note","व्हॉइस मेसेज","व्हॉट्सअॅपवर आवाज","आवाजाचा मेसेज","आवाजात मेसेज","आवाज संदेश","आवाज़ वाला संदेश"],"id":"wa-voice","en":"Open WhatsApp and choose a chat. Press and hold the microphone while you speak, then let go to send.","hi":"व्हाट्सऐप में बातचीत चुनें। बोलते समय माइक्रोफ़ोन दबाकर रखें और भेजने के लिए छोड़ दें।","mr":"व्हॉट्सअॅपमध्ये चॅट निवडा. बोलताना मायक्रोफोन दाबून ठेवा आणि पाठवण्यासाठी सोडा."},{"terms":["video call","व्हिडिओ कॉल","व्हॉट्सअॅप व्हिडिओ","व्हिडिओ कॉल कसा","वीडियो कॉल"],"id":"wa-video","en":"Open a trusted person’s chat in WhatsApp. Tap the video camera near their name. Tap the red button to end the call.","hi":"व्हाट्सऐप में भरोसेमंद व्यक्ति की बातचीत खोलें। नाम के पास वीडियो कैमरा दबाएँ। कॉल बंद करने के लिए लाल बटन दबाएँ।","mr":"व्हॉट्सअॅपमध्ये विश्वासू व्यक्तीची चॅट उघडा. नावाजवळचा व्हिडिओ कॅमेरा दाबा. कॉल बंद करण्यासाठी लाल बटण दाबा."},{"terms":["brightness","ब्राइटनेस","उजेड","प्रकाश","रोशनी","चमक"],"id":"brightness","en":"Swipe down from the top of the screen. Find the sun symbol, then move its bar to change the brightness.","hi":"स्क्रीन के ऊपर से नीचे खींचें। सूरज का निशान ढूँढ़ें और रोशनी बदलने के लिए पट्टी खिसकाएँ।","mr":"स्क्रीनच्या वरून खाली सरकवा. सूर्याचे चिन्ह शोधा आणि उजेड बदलण्यासाठी पट्टी सरकवा."},{"terms":["upi pin","यूपीआई पिन","युपीआय पिन","यूपीआयचा पिन"],"id":"upi-pin","en":"Your UPI PIN is private. Use it only to approve a payment you started. Never tell it to anyone or enter it to receive money.","hi":"आपका UPI PIN गुप्त है। इसे सिर्फ़ अपने शुरू किए भुगतान की मंज़ूरी के लिए डालें। किसी को न बताएँ और पैसे पाने के लिए न डालें।","mr":"तुमचा UPI PIN गुप्त आहे. तुम्ही सुरू केलेले पेमेंट मंजूर करण्यासाठीच तो वापरा. कोणालाही सांगू नका किंवा पैसे मिळवण्यासाठी टाकू नका."},{"terms":["otp","ओटीपी","ओटिपी","one time password"],"id":"otp","en":"An OTP is a one-time code. Enter it only in an app you opened yourself. Never share it with anyone, even someone claiming to be from a bank.","hi":"OTP एक बार का कोड है। इसे सिर्फ़ अपने खोले ऐप में डालें। बैंक का नाम लेने वाले व्यक्ति को भी न बताएँ।","mr":"OTP हा एकदाच वापरायचा कोड आहे. तो स्वतः उघडलेल्या अॅपमध्येच टाका. बँकेचे नाव सांगणाऱ्या व्यक्तीलाही देऊ नका."},{"terms":["upi","यूपीआई"],"id":"upi","en":"UPI lets you send money between bank accounts using a payment app. Practice here is only a sample; never share your PIN.","hi":"UPI से भुगतान ऐप के ज़रिए बैंक खाते में पैसे भेज सकते हैं। यहाँ सिर्फ़ नमूना अभ्यास है; PIN कभी न बताएँ।","mr":"UPI मुळे पेमेंट अॅप वापरून बँक खात्यांमध्ये पैसे पाठवता येतात. इथे फक्त नमुना सराव आहे; PIN कधीही सांगू नका."},{"terms":["call","कॉल","फोन","फोन लावायचा"],"id":"make-call","en":"Open your Phone app, choose a saved contact and tap the phone symbol. This app only lets you practice; no real call is made.","hi":"फ़ोन ऐप खोलें, सहेजा हुआ संपर्क चुनें और फ़ोन का निशान दबाएँ। यहाँ सिर्फ़ अभ्यास है, असली कॉल नहीं।","mr":"फोन अॅप उघडा, जतन केलेला संपर्क निवडा आणि फोनचे चिन्ह दाबा. इथे फक्त सराव आहे, खरा कॉल नाही."},{"terms":["password","पासवर्ड"],"id":"passwords","en":"Use a long, different password for each account. Keep it private and do not share it in a call or message.","hi":"हर खाते के लिए अलग और लंबा पासवर्ड रखें। इसे गुप्त रखें और कॉल या संदेश में न बताएँ।","mr":"प्रत्येक खात्यासाठी वेगळा आणि मोठा पासवर्ड ठेवा. तो गुप्त ठेवा आणि कॉल किंवा मेसेजमध्ये सांगू नका."},{"terms":["wifi","वाई-फाय","वाय-फाय"],"id":"wifi","en":"Open Settings, tap Wi-Fi and choose a network you know. Only enter its password if you trust the network owner.","hi":"सेटिंग में वाई-फ़ाई दबाएँ और जाना-पहचाना नेटवर्क चुनें। भरोसा हो तभी पासवर्ड डालें।","mr":"सेटिंगमध्ये वाय-फाय दाबा आणि ओळखीचे नेटवर्क निवडा. विश्वास असेल तरच पासवर्ड टाका."}],"quizExplanations":[{"en":"A bank will never ask you to tell an OTP. Hang up and contact the bank using its official number.","hi":"बैंक कभी OTP बताने को नहीं कहता। फ़ोन काटें और आधिकारिक नंबर पर बैंक से संपर्क करें।","mr":"बँक कधीही OTP सांगायला सांगत नाही. फोन ठेवा आणि अधिकृत नंबरवर बँकेशी संपर्क करा."},{"en":"The number printed on your card is a trusted way to contact your bank.","hi":"कार्ड पर दिया नंबर बैंक से संपर्क करने का भरोसेमंद तरीका है।","mr":"कार्डवर दिलेला नंबर बँकेशी संपर्क करण्याचा विश्वासू मार्ग आहे."},{"en":"Unexpected prize links can steal information. Do not open them.","hi":"अचानक आए इनाम के लिंक जानकारी चुरा सकते हैं। उन्हें न खोलें।","mr":"अचानक आलेल्या बक्षिसाच्या लिंक माहिती चोरू शकतात. त्या उघडू नका."},{"en":"A long, different password is harder to guess and helps protect your accounts.","hi":"लंबा और अलग पासवर्ड पहचानना मुश्किल होता है और खाते बचाता है।","mr":"मोठा आणि वेगळा पासवर्ड ओळखणे कठीण असते आणि खाती सुरक्षित राहतात."},{"en":"A stranger should not ask you to install an app or access your bank account.","hi":"अनजान व्यक्ति को ऐप डलवाने या बैंक खाते तक पहुँचने न दें।","mr":"अनोळखी व्यक्तीला अॅप बसवू देऊ नका किंवा बँक खात्यापर्यंत पोहोचू देऊ नका."},{"en":"A familiar saved number is usually safer. Still verify requests for money or private details.","hi":"पहचाना नंबर आमतौर पर सुरक्षित है। पैसे या निजी जानकारी की माँग फिर भी जाँचें।","mr":"ओळखीचा नंबर सहसा सुरक्षित असतो. तरीही पैसे किंवा खाजगी माहितीच्या मागणीची खात्री करा."},{"en":"A UPI PIN approves money you send. You never need to share it to receive a refund.","hi":"UPI PIN भेजे गए पैसे मंज़ूर करता है। रिफंड पाने के लिए इसे नहीं बताना पड़ता।","mr":"UPI PIN तुम्ही पाठवलेले पैसे मंजूर करतो. परतावा मिळवण्यासाठी तो सांगावा लागत नाही."},{"en":"Checking with someone you trust before opening a surprise link is a good safety step.","hi":"अनजान लिंक खोलने से पहले भरोसेमंद व्यक्ति से पूछना अच्छा सुरक्षा कदम है।","mr":"अनोळखी लिंक उघडण्याआधी विश्वासू व्यक्तीला विचारणे हा चांगला सुरक्षिततेचा उपाय आहे."},{"en":"A real helper should not need to see your screen unexpectedly. Do not share it with callers.","hi":"असली मददगार को अचानक आपकी स्क्रीन देखने की ज़रूरत नहीं होती। कॉल करने वालों से साझा न करें।","mr":"खऱ्या मदतनीसाला अचानक तुमची स्क्रीन पाहण्याची गरज नसते. फोन करणाऱ्यांसोबत शेअर करू नका."},{"en":"Keep your lock code private. If a caller worries you, hang up and ask someone you trust.","hi":"लॉक कोड गुप्त रखें। कॉल से चिंता हो तो फ़ोन काटें और भरोसेमंद व्यक्ति से पूछें।","mr":"लॉक कोड गुप्त ठेवा. फोनमुळे काळजी वाटल्यास फोन ठेवा आणि विश्वासू व्यक्तीला विचारा."}],"quizOutcome":{"en":{"right":"That is right.","wrong":"Not quite."},"hi":{"right":"सही जवाब।","wrong":"यह सही जवाब नहीं है।"},"mr":{"right":"बरोबर उत्तर.","wrong":"हे बरोबर उत्तर नाही."}},"recognitionErrors":{"not-allowed":{"en":"Microphone access is blocked. Allow it in your browser, or tap a question below.","hi":"माइक्रोफ़ोन की अनुमति बंद है। ब्राउज़र में अनुमति दें या नीचे सवाल चुनें।","mr":"मायक्रोफोनची परवानगी बंद आहे. ब्राउझरमध्ये परवानगी द्या किंवा खालील प्रश्न निवडा."},"service-not-allowed":{"en":"Voice service is blocked here. Tap a question below or type one instead.","hi":"यहाँ आवाज़ सेवा बंद है। नीचे सवाल चुनें या लिखें।","mr":"इथे आवाज सेवा बंद आहे. खालील प्रश्न निवडा किंवा लिहा."},"language-not-supported":{"en":"This browser cannot listen in this language. Tap a question below or type one instead.","hi":"यह ब्राउज़र इस भाषा में नहीं सुन सकता। नीचे सवाल चुनें या लिखें।","mr":"हा ब्राउझर या भाषेत ऐकू शकत नाही. खालील प्रश्न निवडा किंवा लिहा."},"network":{"en":"Voice service needs an internet connection. Tap a question below or type one instead.","hi":"आवाज़ सेवा के लिए इंटरनेट चाहिए। नीचे सवाल चुनें या लिखें।","mr":"आवाज सेवेसाठी इंटरनेट लागते. खालील प्रश्न निवडा किंवा लिहा."},"no-speech":{"en":"I did not hear you. Try speaking again, or tap a question below.","hi":"मुझे आपकी आवाज़ नहीं सुनाई दी। फिर बोलें या नीचे सवाल चुनें।","mr":"मला तुमचा आवाज ऐकू आला नाही. पुन्हा बोला किंवा खालील प्रश्न निवडा."}},"speechUnavailableMessages":{"en":"Saathi could not prepare the audio. Check your internet connection and try again. The answer is still shown here.","hi":"साथी आवाज़ तैयार नहीं कर पाया। इंटरनेट जाँचें और फिर कोशिश करें। जवाब यहाँ लिखा हुआ है।","mr":"साथीला आवाज तयार करता आला नाही. इंटरनेट तपासा आणि पुन्हा प्रयत्न करा. उत्तर इथे लिहिलेले आहे."},"speechLoadingMessages":{"en":"Preparing speech…","hi":"आवाज़ तैयार हो रही है…","mr":"आवाज तयार होत आहे…"}}}'::jsonb)
on conflict (id) do update set payload = excluded.payload, updated_at = now();
